import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public final class MutationCheck {
    static final Path IMPL = Path.of("CalendarUtil.java");
    static final String[][] MUTANTS = {
        // century rule dropped: 1900 becomes a leap year
        {"        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;",
         "        return year % 4 == 0 || year % 400 == 0;"},
        // February never leaps
        {"            case 2: return isLeapYear(year) ? 29 : 28;",
         "            case 2: return 28;"},
        // August demoted to 30 days (and November promoted)
        {"            case 4: case 6: case 9: case 11: return 30;",
         "            case 4: case 6: case 8: case 9: return 30;"},
    };

    public static void main(String[] args) throws Exception {
        String src = Files.readString(IMPL, StandardCharsets.UTF_8);
        for (String[] m : MUTANTS) {
            if (src.split(java.util.regex.Pattern.quote(m[0]), -1).length - 1 != 1) {
                fail("protected implementation file was modified - anchor not found exactly once: " + m[0].trim());
            }
        }
        if (run() != 0) fail("model tests FAILED against the correct implementation");
        try {
            for (int i = 0; i < MUTANTS.length; i++) {
                Files.writeString(IMPL, src.replace(MUTANTS[i][0], MUTANTS[i][1]), StandardCharsets.UTF_8);
                if (run() == 0) fail("mutation " + (i + 1) + " SURVIVED: the tests do not verify the required behavior");
            }
        } finally {
            Files.writeString(IMPL, src, StandardCharsets.UTF_8);
        }
        System.out.println("PASS (killed all " + MUTANTS.length + " mutants)");
    }

    static int run() throws IOException, InterruptedException {
        int compile = exec("javac", "CalendarUtil.java", "CalendarUtilTest.java");
        if (compile != 0) return compile;
        return exec("java", "-ea", "CalendarUtilTest");
    }

    static int exec(String... cmd) throws IOException, InterruptedException {
        return new ProcessBuilder(cmd).inheritIO().start().waitFor();
    }

    static void fail(String message) {
        System.err.println(message);
        System.exit(1);
    }
}

