public final class CalendarUtilTest {
    public static void main(String[] args) {
        check(2024, 2, 29);
        check(2023, 2, 28);
        check(1900, 2, 28);
        check(2000, 2, 29);
        check(2026, 8, 31);
        check(2026, 11, 30);
        check(2026, 4, 30);
        check(2026, 12, 31);

        expectThrow(2026, 0);
        expectThrow(2026, 13);

        System.out.println("all tests passed");
    }

    static void check(int year, int month, int expected) {
        int got = CalendarUtil.daysInMonth(year, month);
        if (got != expected) {
            throw new AssertionError("daysInMonth(" + year + ", " + month + ") = " + got
                    + ", expected " + expected);
        }
    }

    static void expectThrow(int year, int month) {
        try {
            CalendarUtil.daysInMonth(year, month);
        } catch (IllegalArgumentException e) {
            return;
        }
        throw new AssertionError("month " + month + " must throw IllegalArgumentException");
    }
}

