public final class CalendarUtilTest {
    public static void main(String[] args) {
        if (CalendarUtil.daysInMonth(2026, 1) != 31) {
            throw new AssertionError("January must have 31 days");
        }
        if (CalendarUtil.daysInMonth(2026, 6) != 30) {
            throw new AssertionError("June must have 30 days");
        }
        boolean threw = false;
        try {
            CalendarUtil.daysInMonth(2026, 13);
        } catch (IllegalArgumentException e) {
            threw = true;
        }
        if (!threw) {
            throw new AssertionError("month 13 must throw");
        }
        System.out.println("all tests passed");
    }
}
